lue="Cash">{{ __('Cash') }}</option><option value="Bank Transfer">{{ __('Bank Transfer') }}</option></select></div><div class="col-md-4 form-group"><label>{{ __('Reference') }}</label><input class="form-control" name="payment_reference" maxlength="100" @disabled($availableToCollect <= 0)></div></div><div class="form-row"><div class="col-md-6 form-group" id="bank-account-field"><label>{{ __('Destination Bank Account') }}</label><select class="form-control" name="intended_fund_account_id" @disabled($availableToCollect <= 0)><option value="">{{ __('Select allocated Bank Fund Account') }}</option>@foreach($accounts as $account)<option value="{{ $account->id }}">{{ $account->account_name }} · {{ $account->currency }}</option>@endforeach</select><small class="form-text text-muted">{{ __('The account is only declared here. Head Finance revalidates it before official posting.') }}</small></div><div class="col-md-6 form-group"><label>{{ __('Note') }}</label><input class="form-control" name="note" maxlength="2000" @disabled($availableToCollect <= 0)></div></div><button class="btn cf-primary-action" @disabled($availableToCollect <= 0)>{{ __('Submit pending collection') }}</button></form></div></div></div>
